assword" minlength="14" required></label><label>ROLE<select name="role"><?php foreach(['reporter','investigative_reporter','fact_checker','copy_editor','photographer','video_producer','multimedia_editor','section_editor','managing_editor','editor_in_chief','legal_reviewer','medical_reviewer','seo_audience_editor','social_media_manager','advertising_manager','finance_officer','subscriber_support','external_contributor','publisher','system_administrator'] as $role):?><option value="<?=$role?>"><?=e(str_replace('_',' ',ucwords($role,'_')))?></option><?php endforeach;?></select></label><button type="submit">CREATE ACCOUNT →</button></form></div>
